import{_ as e}from"./chunks/11-settings.B_GZgwvL.js";import{_ as a,o as d,c as i,a2 as o}from"./chunks/framework.DUZafPzB.js";const u=JSON.parse('{"title":"Agent config & updates","description":"","frontmatter":{},"headers":[],"relativePath":"ops/agent.md","filePath":"ops/agent.md","lastUpdated":1791422495000}'),n={name:"ops/agent.md"};function r(s,t,l,c,p,h){return d(),i("div",null,[...t[0]||(t[0]=[o('<h1 id="agent-config-updates" tabindex="-1">Agent config &amp; updates <a class="header-anchor" href="#agent-config-updates" aria-label="Permalink to &quot;Agent config &amp; updates&quot;">​</a></h1><p>Install an Agent on every host you want to browse; it dials out to the Hub. Install steps: <a href="/filebox/guide/install-agent">Install Agent</a>.</p><h2 id="state-and-config" tabindex="-1">State and config <a class="header-anchor" href="#state-and-config" aria-label="Permalink to &quot;State and config&quot;">​</a></h2><ul><li>Config file: <code>agent.toml</code> (created by <code>--init-config</code>, mode 0600).</li><li>State directory defaults under the system data dir as <code>filebox</code> (override with <code>FILEBOX_AGENT_DATA_DIR</code>).</li><li>Roots, pins, and collections are pushed from the UI and persisted; bad updates do not wipe the last good config.</li><li>After disconnects it reconnects indefinitely with a stable identity — no duplicate sidebar entries.</li><li>Multiple instances must use different <code>FILEBOX_AGENT_DATA_DIR</code> values.</li></ul><h2 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to &quot;Environment variables&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Meaning</th></tr></thead><tbody><tr><td><code>FILEBOX_AGENT_HUB</code></td><td>Hub URL (<code>https://</code> / <code>wss://</code>)</td></tr><tr><td><code>FILEBOX_AGENT_TOKEN</code></td><td>Agent token</td></tr><tr><td><code>FILEBOX_AGENT_NAME</code></td><td>Sidebar display name</td></tr><tr><td><code>FILEBOX_AGENT_DATA_DIR</code></td><td>State directory</td></tr><tr><td><code>FILEBOX_ALLOW_INSECURE_HUB</code></td><td>Allow plaintext Hub (dev only)</td></tr><tr><td><code>FILEBOX_AGENT_SOFFICE</code> / <code>_DIR</code></td><td>LibreOffice (optional)</td></tr><tr><td><code>FILEBOX_AGENT_TERMINAL_TOTP_SECRET</code></td><td>Terminal 2FA (optional)</td></tr><tr><td><code>FILEBOX_AGENT_STATS_TTL_SECS</code></td><td>sysinfo cache TTL (default 60)</td></tr><tr><td><code>FILEBOX_AGENT_DIR_CACHE_RESTAT_COOLDOWN_MS</code></td><td>Directory cache re-stat cooldown</td></tr></tbody></table><p>Office-related limits: <a href="./office">Office preview</a>.</p><h2 id="updates" tabindex="-1">Updates <a class="header-anchor" href="#updates" aria-label="Permalink to &quot;Updates&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">./agent</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --update</span></span></code></pre></div><p>Verifies checksums and replaces in place. Prefer upgrading with Hub and frontend major versions together.</p><h2 id="optional-capability-switches" tabindex="-1">Optional capability switches <a class="header-anchor" href="#optional-capability-switches" aria-label="Permalink to &quot;Optional capability switches&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Capability</th><th>Where to configure</th></tr></thead><tbody><tr><td>Office preview</td><td><a href="./office">Office preview</a></td></tr><tr><td>Terminal 2FA</td><td><code>./agent --setup-terminal-2fa</code> or env — see <a href="/filebox/features/terminal">Terminal</a></td></tr><tr><td>Transfer</td><td>Capability <code>temp_upload</code>; rules in <a href="/filebox/features/transfer">Transfer</a></td></tr></tbody></table><p>Confirm connection status and enabled roots in UI <strong>Settings</strong>:</p><p><img src="'+e+'" alt="Settings"></p>',14)])])}const b=a(n,[["render",r]]);export{u as __pageData,b as default};
